import java.util.*;

public class Main {
    static List<String> summaryRangesBrute(int[] nums) {
        List<String> result = new ArrayList<>();
        int n = nums.length, i = 0;
        while (i < n) {
            int j = i;
            while (j + 1 < n && nums[j + 1] == nums[j] + 1) j++;    // scan forward for the run's end
            result.add(i == j ? String.valueOf(nums[i]) : nums[i] + "->" + nums[j]);
            i = j + 1;
        }
        return result;
    }
}

